import numpy as np
def equation(t, A, params):
    p = params
    g = (p[0]/t + p[1]*t**p[2])*A**p[3]/(1 + p[4]*A*t**p[5])
    h = p[6]*A**p[7]*t**p[8] + p[9]*A*np.exp(-t)
    return -(g + h)

